      @statement statement
      @sqlstate sqlstate
      @tag [{String.to_atom("enforcement_" <> String.replace(rule, "-", "_") <> "_mutation"), true}]
      test "#{partitioning || "plain"}: #{@label}", c do
        assert :ok = SchemaFixture.install!(c, @table)
        previous = Repo.put_dynamic_repo(c.owner_repo)

        try do
          Repo.transaction(fn ->
            SQL.query!(c.owner_repo, "SET LOCAL session_replication_role=replica", [])

            for statement <- @prelude do
              SQL.query!(c.owner_repo, String.replace(statement, "@schema@", q(c.schema)), [])
            end

            assert {:error, %Postgrex.Error{postgres: %{pg_code: @sqlstate}}} =
                     SQL.query(c.owner_repo, String.replace(@statement, "@schema@", q(c.schema)), [])

            Repo.rollback(:constraint_checked)
          end)
        after
          Repo.put_dynamic_repo(previous)
        end
      end
    end
